{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "live-chat",
  "label": "Live chat",
  "category": "forms",
  "renderMode": "static",
  "targets": [
    "web",
    "mobile"
  ],
  "htmlContent": "<div class="wf-live-chat wf:fixed wf:bottom-5 wf:z-50" data-wf-live-chat data-position="{{setting:position}}" data-title="{{setting:title}}" data-greeting="{{setting:greeting}}" data-offline="{{setting:offline}}" hidden><section class="wf-live-chat__panel" data-wf-chat-panel hidden><header class="wf-live-chat__bar"><strong data-wf-chat-heading></strong><button type="button" data-wf-chat-close>Zatvori</button></header><p class="wf-live-chat__status" data-wf-chat-status></p><p class="wf-live-chat__expected" data-wf-chat-expected></p><div class="wf-live-chat__log" data-wf-chat-log></div><form class="wf-live-chat__form" data-wf-chat-form><div data-wf-chat-identity hidden><input data-wf-chat-name type="text" name="name" maxlength="120" autocomplete="name" placeholder="Ime"><input data-wf-chat-email type="email" name="email" maxlength="200" autocomplete="email" placeholder="Email"></div><textarea data-wf-chat-text name="message" rows="3" maxlength="4000" placeholder="Poruka"></textarea><input data-wf-chat-file type="file" name="file"><button type="submit">Pošalji</button></form></section><button class="wf-live-chat__open" type="button" data-wf-chat-open aria-expanded="false">{{setting:title}}</button></div>",
  "styles": [
    {
      "name": "live-chat.css",
      "content": ".wf-live-chat{position:fixed;z-index:80;right:1.25rem;bottom:1.25rem;font-family:var(--wf-font-body);color:var(--wf-color-text)}
.wf-live-chat[data-position="left"]{right:auto;left:1.25rem}
.wf-live-chat[hidden]{display:none}
.wf-live-chat__open{min-height:48px;border:1px solid var(--wf-color-border);border-radius:999px;background:var(--wf-color-primary);color:#fff;font:inherit;font-weight:var(--wf-heading-weight);padding:.7rem 1.1rem;cursor:pointer;box-shadow:0 10px 24px rgba(15,23,42,.18)}
.wf-live-chat__panel{display:flex;flex-direction:column;width:min(22rem,calc(100vw - 2rem));height:min(34rem,calc(100vh - 7rem));margin-bottom:.6rem;border:1px solid var(--wf-color-border);border-radius:var(--wf-radius);background:var(--wf-color-surface);box-shadow:0 18px 40px rgba(15,23,42,.18);overflow:hidden}
.wf-live-chat__panel[hidden]{display:none}
.wf-live-chat__bar{display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.75rem .9rem;background:var(--wf-color-primary);color:#fff}
.wf-live-chat__bar button{border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}
