  "scripts": [
    {
      "name": "live-chat.js",
      "content": "(function () {
  var root = document.querySelector('[data-wf-live-chat]');
  if (!root || root.getAttribute('data-wf-ready') === 'true') {
    return;
  }
  root.setAttribute('data-wf-ready', 'true');
  var endpoint = '/incKomponente/webchat.php';
  var storeKey = 'wfLiveChatToken';
  var openBtn = root.querySelector('[data-wf-chat-open]');
  var panel = root.querySelector('[data-wf-chat-panel]');
  var closeBtn = root.querySelector('[data-wf-chat-close]');
  var log = root.querySelector('[data-wf-chat-log]');
  var form = root.querySelector('[data-wf-chat-form]');
  var status = root.querySelector('[data-wf-chat-status]');
  var expected = root.querySelector('[data-wf-chat-expected]');
  var nameInput = root.querySelector('[data-wf-chat-name]');
  var emailInput = root.querySelector('[data-wf-chat-email]');
  var textInput = root.querySelector('[data-wf-chat-text]');
  var fileInput = root.querySelector('[data-wf-chat-file]');
  var identity = root.querySelector('[data-wf-chat-identity]');
  var heading = root.querySelector('[data-wf-chat-heading]');
  var timer = 0;
  var cursor = 0;
  var threadReady = false;
  var state = { enabled: false, uploads: false, askIdentity: false, loggedIn: false };
  if (heading) {
    heading.textContent = root.getAttribute('data-title') || 'Razgovor';
  }

  function token() {
    try {
      return localStorage.getItem(storeKey) || '';
    } catch (error) {
      return '';
    }
  }

  function saveToken(value) {
    try {
      if (value) {
        localStorage.setItem(storeKey, value);
      } else {
        localStorage.removeItem(storeKey);
      }
    } catch (error) {
      return;
    }
  }

  function paintStatus(data) {
    var greeting = root.getAttribute('data-greeting') || '';
    var offline = root.getAttribute('data-offline') || '';
    var text = data && data.message ? data.message : (data && data.live ? greeting : offline);
    if (status) {
      status.textContent = text || '';
    }
    if (expected) {
      expected.textContent = data && data.expected ? data.expected : '';
    }
    root.setAttribute('data-live', data && data.live ? 'true' : 'false');
  }

  function addMessage(message) {
    if (!log || !message || log.querySelector('[data-id="' + message.id + '"]')) {
      return;
    }
    var item = document.createElement('div');
    item.className = 'wf-live-chat__msg' + (message.mine ? ' is-mine' : '');
    item.setAttribute('data-id', String(message.id));
    var body = document.createElement('p');
    body.textContent = message.text || '';
    item.appendChild(body);
    if (message.file && message.file.url) {
      var link = document.createElement('a');
      link.href = message.file.url;
      link.target = '_blank';
      link.rel = 'noopener';
      link.textContent = message.file.name || 'Prilog';
      item.appendChild(link);
    }
    log.appendChild(item);
    log.scrollTop = log.scrollHeight;
  }

  function applyThread(data) {
    if (!data) {
      return;
    }
    if (data.reset) {
      saveToken('');
      cursor = 0;
      if (log) {
        log.textContent = '';
      }
    }
    if (data.token) {
      saveToken(data.token);
    }
    if (typeof data.cursor === 'number') {
      cursor = data.cursor;
    }
    (data.messages || []).forEach(addMessage);
    paintStatus(data);
    if (data.closed && status) {
      status.textContent = 'Razgovor je zatvoren. Nova poruka otvara novi.';
    }
  }

  function applyConfig(data) {
    state = data || state;
    if (!data || data.enabled === false) {
      root.setAttribute('hidden', 'hidden');
      return;
    }
    root.removeAttribute('hidden');
    if (identity) {
      identity.hidden = !!data.loggedIn || !data.askIdentity;
    }
    if (fileInput) {
      fileInput.hidden = !data.uploads;
      if (data.types && data.types.length) {
        fileInput.accept = data.types.map(function (ext) { return '.' + ext; }).join(',');
      }
    }
    paintStatus(data);
    applyThread(data);
  }

  function request(action, extra) {
    var url = endpoint + '?action=' + encodeURIComponent(action) + (extra && extra.query ? extra.query : '');
    var options = { credentials: 'same-origin', headers: { 'Accept': 'application/json' } };
    if (extra && extra.body) {
      options.method = 'POST';
      options.body = extra.body;
      if (!(extra.body instanceof FormData)) {
        options.headers['Content-Type'] = 'application/json';
      }
    }
    return fetch(url, options).then(function (response) {
      return response.json().catch(function () { return { ok: false }; });
    });
  }

  function refresh() {
    var current = token();
    var action = 'poll';
    var query = endpoint + '?action=' + action + '&cursor=' + encodeURIComponent(String(cursor));
    if (current) {
      query += '&token=' + encodeURIComponent(current);
    }
    return fetch(query, { credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function (response) { return response.json(); })
      .then(applyThread)
      .catch(function () { return null; });
  }

  function startPoll() {
    stopPoll();
    timer = window.setInterval(refresh, 3000);
  }

  function stopPoll() {
    if (timer) {
      window.clearInterval(timer);
      timer = 0;
    }
  }

  function setOpen(isOpen) {
    if (!panel || !openBtn) {
      return;
    }
    panel.hidden = !isOpen;
    openBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    if (isOpen) {
      var ready = threadReady ? Promise.resolve() : request('open', { query: token() ? '&token=' + encodeURIComponent(token()) : '' }).then(function (data) {
        threadReady = true;
        applyThread(data);
      });
      ready.then(function () {
        refresh();
        startPoll();
        if (textInput) {
          textInput.focus();
        }
      });
    } else {
      stopPoll();
    }
  }

  if (openBtn) {
    openBtn.addEventListener('click', function () { setOpen(panel.hidden); });
  }
  if (closeBtn) {
    closeBtn.addEventListener('click', function () { setOpen(false); });
  }
  if (form) {
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var data = new FormData();
      data.append('action', 'send');
      data.append('token', token());
      data.append('text', textInput ? textInput.value : '');
      data.append('name', nameInput ? nameInput.value : '');
      data.append('email', emailInput ? emailInput.value : '');
      if (fileInput && fileInput.files && fileInput.files[0]) {
        data.append('file', fileInput.files[0]);
      }
      request('send', { body: data }).then(function (payload) {
        if (!payload || payload.ok === false) {
          if (status) {
            status.textContent = payload && payload.error ? payload.error : 'Poruka nije poslata.';
          }
          return;
        }
        if (textInput) {
          textInput.value = '';
        }
        if (fileInput) {
          fileInput.value = '';
        }
        if (log) {
          log.textContent = '';
        }
        cursor = 0;
        applyThread(payload);
      }).catch(function () {
        if (status) {
          status.textContent = 'Poruka nije poslata.';
        }
      });
    });
  }

  request('duty').then(applyConfig).catch(function () {
    root.setAttribute('hidden', 'hidden');
  });
})();
"
    }
  ],
