{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "starter-header-visual",
  "label": "Zaglavlje sa logom",
  "category": "content",
  "renderMode": "static",
  "targets": [
    "web",
    "mobile"
  ],
  "htmlContent": "<header class=\"wfv-header\" data-variant=\"{{setting:variant}}\"><a class=\"wfv-brand\" href=\"{{setting:home-url}}\"><img src=\"{{setting:logo-url}}\" alt=\"{{setting:logo-alt}}\"><span>{{setting:brand}}</span></a><div class=\"wfv-menu\"><button type=\"button\" class=\"wfv-menu-toggle\" aria-expanded=\"false\">Meni</button><nav aria-label=\"Glavna navigacija\">{{each:links}}<a href=\"{{item:url}}\">{{item:label}}</a>{{/each:links}}</nav></div><div class=\"wfv-actions\">{{slot:actions}}</div></header>",
  "styles": [
    {
      "name": "starter-header-visual.css",
      "content": ".wfv-header{max-width:var(--wf-container-max-width,1160px);margin:auto;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:24px;font-family:var(--wf-font-body,system-ui)}.wfv-header a{color:inherit;text-decoration:none}.wfv-brand{display:flex;align-items:center;gap:12px;font-weight:800;font-size:20px}.wfv-brand img{height:44px;width:auto;max-width:180px;object-fit:contain}.wfv-brand img[src=\"\"]{display:none}.wfv-header nav{display:flex;gap:20px;flex-wrap:wrap}.wfv-header a:focus-visible,.wfv-menu-toggle:focus-visible{outline:2px solid currentColor;outline-offset:4px}.wfv-menu-toggle{cursor:pointer;min-height:44px;padding:12px;background:transparent;color:inherit;border:1px solid currentColor;border-radius:4px}.wfv-header[data-variant=\"center\"],.wfv-header[data-variant=\"below\"]{flex-direction:column}.wfv-header[data-variant=\"below\"] .wfv-brand{align-self:flex-start}@media(min-width:701px){.wfv-menu-toggle{display:none}.wfv-menu:not([open])>nav{display:flex}}@media(max-width:700px){.wfv-header{padding:16px;align-items:stretch;flex-direction:column;gap:8px}.wfv-brand img{max-width:140px}.wfv-menu nav{flex-direction:column;gap:0}.wfv-menu nav a{padding:12px}.wfv-menu-toggle{display:inline-flex}.wfv-header[data-menu-ready=\"true\"] .wfv-menu nav{display:none}.wfv-header[data-menu-open=\"true\"] .wfv-menu nav{display:flex}} .wfv-header{display:grid;grid-template-columns:auto minmax(0,1fr) auto;color:var(--wf-color-text);background:var(--wf-color-surface)}.wfv-header>*{min-width:0}.wfv-menu{justify-self:end}.wfv-actions>.wf-slot{display:flex;align-items:center;justify-content:flex-end;gap:16px;flex-wrap:wrap}.wfv-actions:not(:has(.wf-instance)){display:none}.wfv-header[data-variant=\"center\"]{grid-template-columns:minmax(0,1fr) auto minmax(0,1fr)}.wfv-header[data-variant=\"center\"] .wfv-brand{grid-column:2;grid-row:1;justify-self:center}.wfv-header[data-variant=\"center\"] .wfv-menu{grid-column:1;grid-row:1;justify-self:start}.wfv-header[data-variant=\"center\"] .wfv-actions{grid-column:3;grid-row:1}.wfv-header[data-variant=\"below\"] .wfv-menu{grid-column:1/-1;grid-row:2;justify-self:start}.wfv-header[data-variant=\"below\"] .wfv-actions{grid-column:3;grid-row:1}.wfv-header[data-variant=\"shop\"] .wfv-menu{justify-self:start}.wfv-header .wf-header-action{display:inline-flex;align-items:center;gap:8px;min-height:44px;font:inherit}.wfv-header .wf-header-action__label{white-space:nowrap}@media(max-width:700px){.wfv-header,.wfv-header[data-variant=\"center\"]{grid-template-columns:minmax(0,1fr) auto;gap:12px}.wfv-header .wfv-brand,.wfv-header[data-variant=\"center\"] .wfv-brand{grid-column:1;grid-row:1;justify-self:start}.wfv-header .wfv-actions,.wfv-header[data-variant=\"center\"] .wfv-actions,.wfv-header[data-variant=\"below\"] .wfv-actions{grid-column:2;grid-row:1}.wfv-header .wfv-menu,.wfv-header[data-variant=\"center\"] .wfv-menu,.wfv-header[data-variant=\"below\"] .wfv-menu{grid-column:1/-1;grid-row:2;justify-self:stretch}.wfv-brand{flex-wrap:wrap;font-size:16px}.wfv-brand img{max-width:100%;height:36px}.wfv-actions>.wf-slot{gap:8px}.wfv-brand span{overflow-wrap:anywhere}.wfv-header nav a{overflow-wrap:anywhere}.wfv-header .wf-header-action{gap:4px}}"
    }
  ],
  "scripts": [
    {
      "name": "starter-header-visual.js",
      "content": "(function(){document.querySelectorAll(\".wfv-header\").forEach(function(root,index){if(root.dataset.menuReady)return;var button=root.querySelector(\".wfv-menu-toggle\"),nav=root.querySelector(\"nav\");if(!button||!nav)return;root.dataset.menuReady=\"true\";nav.id=\"wfv-navigation-\"+index;button.setAttribute(\"aria-controls\",nav.id);button.addEventListener(\"click\",function(){var open=button.getAttribute(\"aria-expanded\")!==\"true\";button.setAttribute(\"aria-expanded\",open?\"true\":\"false\");root.dataset.menuOpen=open?\"true\":\"false\";});});})();"
    }
  ],
  "settingsSchema": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "brand",
      "home-url",
      "links"
    ],
    "properties": {
      "brand": {
        "type": "string",
        "maxLength": 100,
        "minLength": 1
      },
      "home-url": {
        "type": "string",
        "maxLength": 2048,
        "minLength": 1,
        "format": "safe-url"
      },
      "links": {
        "type": "array",
        "minItems": 0,
        "maxItems": 8,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "label",
            "url"
          ],
          "properties": {
            "label": {
              "type": "string",
              "maxLength": 60,
              "minLength": 1
            },
            "url": {
              "type": "string",
              "maxLength": 2048,
              "minLength": 1,
              "format": "safe-url"
            }
          }
        }
      },
      "variant": {
        "type": "string",
        "enum": [
          "left",
          "center",
          "below",
          "shop"
        ],
        "maxLength": 16
      },
      "logo-url": {
        "type": "string",
        "maxLength": 2048,
        "format": "safe-url"
      },
      "logo-alt": {
        "type": "string",
        "maxLength": 160
      }
    }
  },
  "providerKey": null,
  "cache": {
    "scope": "public",
    "ttlSeconds": 3600,
    "varyBy": [
      "tenant",
      "locale",
      "release"
    ]
  },
  "access": {
    "visibility": "public",
    "permissions": []
  },
  "seo": {
    "mode": "none"
  },
  "themeBindings": {
    "brand": "brand.name",
    "logo-url": "brand.logoUrl",
    "logo-alt": "brand.logoAlt"
  },
  "slots": [
    "actions"
  ]
}

